266	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
267	            // above the clerk limit: a steward approves or rejects it
268	            to = ClaimStatus.PENDING;
269	        }
270	        RollupService.Snapshot before = rollup.snapshot(sheetId);
271	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
272	        String number = claim.getNumber();
273	        // a voided SETTLED claim keeps its frozen figure, which leaves every total
274	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
275	        BigDecimal reversed = claim.getSettledDue();
276	        claim.setStatus(to);
277	        if (to == ClaimStatus.OPEN) {
278	            number = nextNumber(sheetId, claim.getDate());
279	            claim.setNumber(number);
280	            claim.setOpenedBy(user);
281	        } else if (to == ClaimStatus.SETTLED) {
282	            claim.setSettledDue(settling);
283	        }
284	        claims.flush();
285	        logStatus(user, person, claim);
286	        String event = switch (to) {
287	            case OPEN -> "CLAIM_OPENED";
288	            case PENDING -> "CLAIM_PENDING";
289	            case SETTLED -> "CLAIM_SETTLED";
290	            case VOID -> "CLAIM_VOIDED";
291	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
292	        };
293	        if (to == ClaimStatus.SETTLED) {
294	            record(event, user, person, claim, number, " due=" + dueText(claim.getSettledDue()));
295	            notifyWatchers(user, person, number);
296	        } else if (reversing) {
297	            record(event, user, person, claim, number, " reversed=" + dueText(reversed));
298	        } else {
299	            record(event, user, person, claim, number);
300	        }
301	        rollup.recordChanges(sheetId, user, before);
302	        return claim;
303	    }
