305	    /** Refuse voiding a SETTLED claim (403) by anyone but a steward, and (409) once the sheet's
306	     *  today is more than {@link ClaimStatus#SETTLED_VOID_DAYS} days after its settlement (the
307	     *  first SETTLED line of its status log). */
308	    private void refuseUnlessVoidableSettled(String sheetId, String user, Claim claim) {
309	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
310	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim");
311	        }
312	        LocalDate settledOn = log.findByClaimIdOrderByIdAsc(claim.getId()).stream()
313	                .filter(line -> line.getStatus() == ClaimStatus.SETTLED)
314	                .map(ClaimLog::getOn)
315	                .findFirst()
316	                .orElse(null);
317	        LocalDate today = sheets.today(sheetId);
318	        if (settledOn == null || today.isAfter(settledOn.plusDays(ClaimStatus.SETTLED_VOID_DAYS))) {
319	            throw new ResponseStatusException(HttpStatus.CONFLICT,
320	                    "A SETTLED claim is voided only within " + ClaimStatus.SETTLED_VOID_DAYS + " days of its settlement");
321	        }
322	    }
