324	    /** Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches
325	     *  it, the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
326	     *  statement. Refused (404) when missing, (423) when dated in a closed period, (409) unless
327	     *  OPEN, and (422) when the date is not after the sheet's today. */
328	    @Transactional
329	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
330	        Claim claim = claims.findForUpdate(id, sheetId)
331	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
