340	        }
341	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
342	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
343	        RollupService.Snapshot before = rollup.snapshot(sheetId);
