351	    /** A steward re-dates an OPEN or PENDING claim: its due-by stays as it was fixed, a figure a
352	     *  statement bound it to stays bound, and its period follows the new date. Under period
353	     *  numbering, when the new date is in another period than the old (or none), the claim takes
354	     *  the next number of the new period's sequence and its old number is never given again.
355	     *  Refused (404) when missing, (403) for anyone but a steward, (423) when its old or new date
356	     *  is in a closed period, (409) unless OPEN or PENDING, and (422) when the new date is after
357	     *  the person's retirement date. */
358	    @Transactional
359	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
360	        Claim claim = claims.findForUpdate(id, sheetId)
361	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
362	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
363	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim");
364	        }
365	        refuseIfClosed(sheetId, claim.getDate());
366	        if (!claim.getStatus().isOpen()) {
367	            throw new ResponseStatusException(HttpStatus.CONFLICT,
368	                    "Only an OPEN or PENDING claim is re-dated, not a " + claim.getStatus() + " one");
369	        }
370	        refuseIfClosed(sheetId, date);
371	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
372	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
373	        refuseIfRetired(person, date);
374	        RollupService.Snapshot before = rollup.snapshot(sheetId);
375	        LocalDate old = claim.getDate();
376	        if (sheets.periodNumberingOn(sheetId) && !samePeriod(sheetId, old, date)) {
377	            String number = nextNumber(sheetId, date);
378	            if (claim.getNumber() != null) {
379	                retired.save(new RetiredNumber(sheetId, claim.getNumber()));
380	            }
381	            claim.setNumber(number);
382	        }
383	        claim.setDate(date);
384	        claims.flush();
385	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), " old=" + old + " new=" + date);
386	        rollup.recordChanges(sheetId, user, before);
387	        return claim;
388	    }
