390	    /** Whether two dates fall in the same period (or both in none). */
391	    private boolean samePeriod(String sheetId, LocalDate a, LocalDate b) {
392	        return periods.containing(sheetId, a).map(Period::getId)
393	                .equals(periods.containing(sheetId, b).map(Period::getId));
394	    }
