441	    /** Refuse (422) settling or approving a claim at a due (null: n/a) above the proof threshold in
442	     *  force on its date while it has no proof. */
443	    private void refuseIfUnproven(Claim claim, BigDecimal due) {
444	        if (claim.getProofs() > 0 || due == null) {
445	            return;
446	        }
447	        BigDecimal threshold = sheets.proofThresholdOn(claim.getSheetId(), claim.getDate());
448	        if (threshold != null && due.compareTo(threshold) > 0) {
449	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
450	                    "A claim whose due is above the proof threshold needs a proof first");
451	        }
452	    }
