454	    /** A steward re-settles a SETTLED claim: its due is frozen again at the figure it would show
455	     *  today as an open claim bound by no statement (today's rates, grades, floor and late
456	     *  charge). Refused (404) when missing, (423) when dated in a closed period, (403) for anyone
457	     *  but a steward, and (409) unless SETTLED. */
458	    @Transactional
459	    public Claim resettle(String sheetId, String user, long id) {
460	        Claim claim = claims.findForUpdate(id, sheetId)
461	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
462	        refuseIfClosed(sheetId, claim.getDate());
463	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
464	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim");
465	        }
466	        if (claim.getStatus() != ClaimStatus.SETTLED) {
467	            throw new ResponseStatusException(HttpStatus.CONFLICT,
468	                    "Only a SETTLED claim is re-settled, not a " + claim.getStatus() + " one");
469	        }
470	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
471	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
472	        RollupService.Snapshot before = rollup.snapshot(sheetId);
473	        BigDecimal old = claim.getSettledDue();
