503	    /** A steward (or a role the permission matrix lets reassign) moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
504	     *  number and date, is listed as the new person's newest claim, and loses any figure a
505	     *  statement bound it to (live again until the new person's next statement). Refused (404)
506	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
507	     *  role the sheet's permission matrix does not let reassign, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
508	     *  the new person's retirement date. */
509	    @Transactional
510	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
511	        Claim claim = claims.findForUpdate(id, sheetId)
512	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
513	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
514	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
515	        refuseIfClosed(sheetId, claim.getDate());
516	        settings.refuseUnlessAllowed(sheetId, user, Permission.REASSIGN);
517	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
518	            throw new ResponseStatusException(HttpStatus.CONFLICT,
519	                    "A " + claim.getStatus() + " claim cannot be reassigned");
520	        }
521	        if (claim.getPersonId() == toPersonId) {
522	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
523	        }
524	        refuseIfRetired(to, claim.getDate());
525	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
526	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
527	        RollupService.Snapshot before = rollup.snapshot(sheetId);
528	        claim.setPersonId(to.getId());
529	        claim.unbind();
530	        claim.setListed(claims.findLastListed(sheetId) + 1);
531	        claims.flush();
532	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
533	                " from=" + from.getName() + " to=" + to.getName());
534	        rollup.recordChanges(sheetId, user, before);
535	        return claim;
536	    }
