538	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any
539	     *  figure a statement bound it to, and a new OPEN claim of the amount, with the same date and
540	     *  note, the next number, opened by the user, its due-by fixed now from the terms in force on
541	     *  the date (the person's own, else their grade's, else the sheet's), and naming the original's number as split-from, is listed as the person's newest.
542	     *  Refused (404) when missing, (423) when dated in a closed period, (403) for a role the
543	     *  sheet's permission matrix does not let open a claim, (409) unless OPEN and not deferred on
544	     *  the sheet's today, and (422) unless the amount is more than 0.00 and less than the claim's. */
545	    @Transactional
546	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
547	        Claim claim = claims.findForUpdate(id, sheetId)
548	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
549	        refuseIfClosed(sheetId, claim.getDate());
550	        settings.refuseUnlessAllowed(sheetId, user, Permission.OPEN);
551	        if (claim.getStatus() != ClaimStatus.OPEN) {
552	            throw new ResponseStatusException(HttpStatus.CONFLICT,
553	                    "Only an OPEN claim is split, not a " + claim.getStatus() + " one");
554	        }
555	        if (claim.isDeferredOn(sheets.today(sheetId))) {
556	            throw new ResponseStatusException(HttpStatus.CONFLICT,
557	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be split before then");
558	        }
559	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
560	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
561	                    "The amount split off must be more than 0.00 and less than the claim's");
562	        }
563	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
564	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
565	        RollupService.Snapshot before = rollup.snapshot(sheetId);
566	        LocalDate on = claim.getDate();
567	        claim.setAmount(claim.getAmount().subtract(amount));
568	        claim.unbind();
569	        int terms = person.getTerms() != null ? person.getTerms()
570	                : sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on), on)).orElse(Sheet.DEFAULT_TERMS);
571	        Claim fresh = new Claim(sheetId, person.getId(), amount, on, on.plusDays(terms), claim.getNote());
572	        fresh.setStatus(ClaimStatus.OPEN);
573	        fresh.setNumber(nextNumber(sheetId, on));
574	        fresh.setOpenedBy(user);
575	        fresh.setSplitFrom(claim.getNumber());
576	        fresh.setListed(claims.findLastListed(sheetId) + 1);
577	        Claim split = claims.saveAndFlush(fresh);
578	        logStatus(user, person, split);
579	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), " into=" + split.getNumber());
580	        record("CLAIM_OPENED", user, person, split);
581	        rollup.recordChanges(sheetId, user, before);
582	        return new Split(claim, split);
583	    }
