614	    /** Take a statement of a person: record their due-total now, and bind each of their claims
615	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
616	     *  are left unbound. */
617	    @Transactional
618	    public Statement statement(String sheetId, String user, long personId) {
619	        Person person = people.findForUpdate(personId, sheetId)
620	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
621	        LocalDate today = sheets.today(sheetId);
622	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
623	        RollupService.Snapshot before = rollup.snapshot(sheetId);
624	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
625	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
626	        for (Claim c : theirs) {
627	            if (counts(c, person, today)) {
628	                // the statement binds the figure; the late charge keeps following the sheet's today
629	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
630	            } else {
631	                c.unbind();
632	            }
633	        }
634	        claims.flush();
635	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
636	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
637	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
638	        rollup.recordChanges(sheetId, user, before);
639	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
640	    }
