642	    /** A steward cancels a person's last statement: it is removed, and every claim it bound is
643	     *  live again (a figure an earlier statement bound is not restored). Refused (404) when the
644	     *  person is missing, (403) for anyone but a steward, and (409) when the person has no
645	     *  statement. */
646	    @Transactional
647	    public Statement cancelStatement(String sheetId, String user, long personId) {
648	        Person person = people.findForUpdate(personId, sheetId)
649	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
650	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
651	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement");
652	        }
653	        List<PersonStatement> taken = statements.findByPersonIdOrderByIdAsc(personId);
654	        if (taken.isEmpty()) {
655	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person has no statement to cancel");
656	        }
657	        PersonStatement last = taken.get(taken.size() - 1);
658	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
659	        RollupService.Snapshot before = rollup.snapshot(sheetId);
660	        theirs.forEach(Claim::unbind);
661	        claims.flush();
662	        statements.delete(last);
663	        statements.flush();
664	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
665	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
666	        rollup.recordChanges(sheetId, user, before);
667	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
668	    }
