670	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
671	     *  and the sheet's today on or after it) the next within the period containing the date
672	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
673	    private String nextNumber(String sheetId, LocalDate date) {
674	        if (!sheets.periodNumberingOn(sheetId)) {
675	            return String.valueOf(sheets.nextClaimNumber(sheetId));
676	        }
677	        // held until the transaction ends, so two claims opened at once are numbered one after the other
678	        sheets.lock(sheetId);
679	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
680	        List<String> given = new ArrayList<>(claims.findNumbers(sheetId));
681	        given.addAll(retired.findNumbers(sheetId));
682	        int last = given.stream()
683	                .filter(n -> n.startsWith(prefix))
684	                .map(n -> n.substring(prefix.length()))
685	                .filter(n -> n.matches("\\d{1,9}"))
686	                .mapToInt(Integer::parseInt)
687	                .max().orElse(0);
688	        return prefix + (last + 1);
689	    }
