691	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
692	     *  the transaction ends so a period cannot be closed meanwhile. */
693	    private void refuseIfClosed(String sheetId, LocalDate date) {
694	        sheets.lock(sheetId);
695	        periods.refuseIfClosed(sheetId, date);
696	    }
697	
698	    /** Refuse (409) a change to a claim whose editor another user holds open. */
699	    private static void refuseIfLocked(Claim claim, String user) {
700	        if (claim.isLockedFor(user)) {
701	            throw new ResponseStatusException(HttpStatus.CONFLICT,
702	                    "The claim is being edited by " + claim.getLockedBy());
703	        }
704	    }
705	
706	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
707	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
708	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
709	        if (amount.signum() >= 0) {
710	            return null;
711	        }
712	        if (corrects == null
713	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
714	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
715	                    "A negative amount must correct a settled claim of the same person");
716	        }
717	        return corrects;
718	    }
719	
720	    /** Refuse (422) a claim dated after its person's retirement date. */
721	    private static void refuseIfRetired(Person person, LocalDate date) {
722	        if (person.retiredBefore(date)) {
723	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
724	                    "The date is after the person's retirement date");
725	        }
726	    }
727	
728	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
729	     *  do, but not an open one dated within a hold of its person, nor one of a person whose
730	     *  retirement date the sheet's today has reached, unless bound by a statement, nor one deferred
731	     *  on the sheet's today. */
732	    private static boolean counts(Claim c, Person person, LocalDate today) {
733	        return c.getStatus() == ClaimStatus.SETTLED
734	                || (c.getStatus().isOpen() && !c.isDeferredOn(today)
735	                        && (c.isBound() || !(person.heldOn(c.getDate()) || person.retiredOn(today))));
736	    }
737	
738	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
739	     *  charge on top, raised to the floor in force on its date. */
740	    private BigDecimal shownDueOf(Claim claim, Person person) {
741	        if (claim.getSettledDue() != null) {
742	            return claim.getSettledDue();
743	        }
744	        return flooredOf(claim,
745	                LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim)));
746	    }
747	
748	    /** A due (null: n/a, which stays n/a) raised to the sheet's floor in force on the claim's date; a
749	     *  correction's never is. */
750	    private BigDecimal flooredOf(Claim claim, BigDecimal due) {
751	        if (due == null || claim.isCorrection()) {
752	            return due;
753	        }
754	        return due.max(sheets.floorOn(claim.getSheetId(), claim.getDate()));
755	    }
756	
757	    /** A claim's figure before any late charge or floor: the one a statement bound it to (null: n/a),
758	     *  else (unbound, or PENDING) its rate figure. */
759	    private BigDecimal figureOf(Claim claim, Person person) {
760	        return claim.isBound() ? claim.getStatedDue() : rateFigureOf(claim, person);
761	    }
762	
763	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
764	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
765	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
766	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
767	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
768	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
769	            return null;
770	        }
771	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
772	    }
773	
774	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
775	     *  100, rounded as its rounding policy has it; null with no rate in force then. */
776	    private BigDecimal rateFigureOf(Claim claim, Person person) {
777	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
778	                .map(Rate::getPct)
779	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
780	                .orElse(null);
781	    }
782	
783	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
784	     *  correction the date of the claim it corrects. */
785	    private RoundingMode roundingOf(Claim claim) {
786	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
787	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
788	                        .map(Claim::getDate).orElse(claim.getDate());
789	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
790	    }
791	
792	    private void record(String event, String user, Person person, Claim claim) {
793	        record(event, user, person, claim, claim.getNumber());
794	    }
795	
796	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
797	    private void record(String event, String user, Person person, Claim claim, String number) {
798	        record(event, user, person, claim, number, "");
799	    }
800	
801	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
802	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
803	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
804	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
805	    }
806	
807	    /** Notify each user watching the person that one of their claims was settled, in the order
808	     *  they started watching. */
809	    private void notifyWatchers(String user, Person person, String number) {
810	        for (PersonWatch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
811	            audit.recordOnCommit("NOTIFY sheet=" + person.getSheetId() + " by=" + user + " user=" + w.getUserName()
812	                    + " person=" + person.getName() + " number=" + number);
813	        }
814	    }
815	
816	    private static String noteOf(String note) {
817	        return note == null ? "" : note.trim();
818	    }
819	}
